content:
{
  "root_cause": "The NHSUK checkboxes module's exclusive group logic requires non-exclusive checkboxes to explicitly declare `data-checkbox-exclusive=\"false\"` to be recognized as part of the exclusive group and be cleared when the exclusive option is selected. Without this attribute, the module does not include them in the clearing operation.",
  "repair_strategy": "Add `data-checkbox-exclusive=\"false\"` to each non-exclusive symptom checkbox (cough, fever, taste) to explicitly mark them as part of the exclusive group, enabling the module to uncheck them when \"No symptoms\" is selected.",
  "edits": [
    {
      "path": "index.html",
      "sha256": "6828d82d86a82e3e4e9364d8442eedcafd0b8f0740235e0d231082ffcd75878e",
      "before": "          <input class=\"nhsuk-checkboxes__input\" id=\"symptoms-cough\" name=\"symptoms[cough]\" type=\"checkbox\" value=\"yes\" data-checkbox-exclusive-group=\"symptoms\">",
      "after": "          <input class=\"nhsuk-checkboxes__input\" id=\"symptoms-cough\" name=\"symptoms[cough]\" type=\"checkbox\" value=\"yes\" data-checkbox-exclusive-group=\"symptoms\" data-checkbox-exclusive=\"false\">"
    },
    {
      "path": "index.html",
      "sha256": "6828d82d86a82e3e4e9364d8442eedcafd0b8f0740235e0d231082ffcd75878e",
      "before": "          <input class=\"nhsuk-checkboxes__input\" id=\"symptoms-fever\" name=\"symptoms[fever]\" type=\"checkbox\" value=\"yes\" data-checkbox-exclusive-group=\"symptoms\">",
      "after": "          <input class=\"nhsuk-checkboxes__input\" id=\"symptoms-fever\" name=\"symptoms[fever]\" type=\"checkbox\" value=\"yes\" data-checkbox-exclusive-group=\"symptoms\" data-checkbox-exclusive=\"false\">"
    },
    {
      "path": "index.html",
      "sha256": "6828d82d86a82e3e4e9364d8442eedcafd0b8f0740235e0d231082ffcd75878e",
      "before": "          <input class=\"nhsuk-checkboxes__input\" id=\"symptoms-taste\" name=\"symptoms[taste]\" type=\"checkbox\" value=\"yes\" data-checkbox-exclusive-group=\"symptoms\">",
      "after": "          <input class=\"nhsuk-checkboxes__input\" id=\"symptoms-taste\" name=\"symptoms[taste]\" type=\"checkbox\" value=\"yes\" data-checkbox-exclusive-group=\"symptoms\" data-checkbox-exclusive=\"false\">"
    }
  ],
  "expected_accessibility_effect": "Keyboard users can select \"No symptoms\" and have previously selected symptom checkboxes automatically cleared, ensuring form state reflects the exclusive choice, satisfying WCAG 2.1.1 (Keyboard), 2.4.3 (Focus Order), and 4.1.2 (Name, Role, Value).",
  "functional_risks": [
    "The added attribute is purely for client-side script; it has no server-side impact.",
    "If other custom scripts depend on the absence of this attribute, they could be affected, but the risk is low."
  ],
  "verification_requirements": [
    "Using only the keyboard, tick a symptom (e.g., cough), then tick \"No symptoms\" and confirm that the symptom checkbox is unticked and the form data contains only symptoms[none]=yes.",
    "Using only the keyboard, tick \"No symptoms\", then tick a symptom and confirm that the \"No symptoms\" checkbox is unticked and the form data contains only the selected symptom.",
    "Verify that the contact group's exclusive behavior (choosing \"Do not contact me\" clears text/email) remains unchanged.",
    "Ensure that screen readers announce the correct state changes when the exclusive option is selected."
  ]
}
